def shoot(x):
    pete_score = 0
    phil_score = 0

    for round_data in x:
        scores, is_exciting = round_data
        p1_hits = scores['P1'].count('X')
        p2_hits = scores['P2'].count('X')

        multiplier = 2 if is_exciting else 1

        pete_score += p1_hits * multiplier
        phil_score += p2_hits * multiplier

    if pete_score > phil_score:
        return "Pete Wins!"
    elif phil_score > pete_score:
        return "Phil Wins!"
    else:
        return "Draw!"
